OYSTER_ALLOWED = {'Bacterial Infection', 'Poor Water Quality / Ammonia-Nitrite Stress'}


def seed_disease_types(apps, schema_editor):
    DiseaseType = apps.get_model('fisheries', 'DiseaseType')
    DiseaseResponseGuide = apps.get_model('fisheries', 'DiseaseResponseGuide')
    SpeciesOption = apps.get_model('fisheries', 'SpeciesOption')

    finfish = list(SpeciesOption.objects.filter(category__name='Finfish'))
    tilapia = list(SpeciesOption.objects.filter(species_name='Tilapia'))
    oyster = list(SpeciesOption.objects.filter(species_name='Oyster'))
    # Shrimp (Crustacean) deliberately gets nothing — see module docstring.

    for entry in DISEASE_TYPES:
        disease_type, _ = DiseaseType.objects.get_or_create(
            name=entry['name'],
            defaults={'description': entry['description'], 'is_active': True},
        )

        if entry['species_group'] == 'tilapia_only':
            disease_type.species_options.set(tilapia)
        else:
            links = list(finfish)
            if disease_type.name in OYSTER_ALLOWED:
                links += oyster
            disease_type.species_options.set(links)

        DiseaseResponseGuide.objects.get_or_create(
            disease_type=disease_type,
            defaults={
                'recommended_treatment': entry['treatment'],
                'notes': NOTES_DISCLAIMER,
            },
        )


